#!/usr/bin/env python3
"""Read-only Lua token inventory; writes only the new October 11 JSON proof."""
import ast
from collections import Counter, defaultdict
from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import re
import sys

ROOT = Path.cwd()
if not (ROOT / 'public/native/scripts.json').is_file():
    ROOT = Path('/workspace/yugioh-25d-holograms')
OUTPUT = ROOT / 'docs/audits/artifacts/token-monster-inventory-2026-10-11/lua-token-generators.json'

@dataclass
class Token:
    value: str
    kind: str
    start: int
    end: int
    line: int

def lex(source):
    """Lua lexical scan: omit comments, retain opaque short/long string tokens."""
    out = []
    p = 0
    line = 1
    while p < len(source):
        ch = source[p]
        if ch.isspace():
            line += ch == '\n'
            p += 1
            continue
        begin = p
        initial_line = line
        if source.startswith('--', p):
            p += 2
            long = re.match(r'\[(=*)\[', source[p:])
            if long:
                closing = ']' + long[1] + ']'
                end = source.find(closing, p + len(long[0]))
                if end < 0:
                    raise ValueError('Unclosed long comment')
                p = end + len(closing)
            else:
                end = source.find('\n', p)
                p = len(source) if end < 0 else end
            line += source[begin:p].count('\n')
            continue
        if ch in "\"'":
            p += 1
            while p < len(source):
                if source[p] == '\\':
                    p += 2
                elif source[p] == ch:
                    p += 1
                    break
                else:
                    p += 1
            else:
                raise ValueError('Unclosed quoted string')
            kind = 'string'
        elif (long := re.match(r'\[(=*)\[', source[p:])):
            closing = ']' + long[1] + ']'
            end = source.find(closing, p + len(long[0]))
            if end < 0:
                raise ValueError('Unclosed long string')
            p = end + len(closing)
            kind = 'string'
        elif (name := re.match(r'[A-Za-z_][A-Za-z_0-9]*', source[p:])):
            p += len(name[0])
            kind = 'identifier'
        elif (number := re.match(r'(?:0[xX][0-9A-Fa-f]+|\d+(?:\.\d+)?)(?:[eEpP][+-]?\d+)?', source[p:])):
            p += len(number[0])
            kind = 'number'
        else:
            operator = next((v for v in ['...', '//', '<<', '>>', '==', '~=', '<=', '>=', '..'] if source.startswith(v, p)), ch)
            p += len(operator)
            kind = 'symbol'
        out.append(Token(source[begin:p], kind, begin, p, initial_line))
        line += source[begin:p].count('\n')
    return out

def compact(tokens):
    return ''.join(t.value for t in tokens)

def close_at(tokens, start):
    expected = {'(': ')', '[': ']', '{': '}'}
    stack = []
    for i in range(start, len(tokens)):
        value = tokens[i].value
        if tokens[i].kind == 'string':
            continue
        if value in expected:
            stack.append(expected[value])
        elif value in expected.values():
            if not stack or stack.pop() != value:
                raise ValueError('Unbalanced brackets')
            if not stack:
                return i
    raise ValueError('Unclosed call or table')

def comma_parts(tokens):
    parts = []
    start = 0
    depth = 0
    for i, token in enumerate(tokens):
        if token.kind == 'string':
            continue
        if token.value in ['(', '[', '{']:
            depth += 1
        elif token.value in [')', ']', '}']:
            depth -= 1
        elif token.value == ',' and depth == 0:
            parts.append(tokens[start:i])
            start = i + 1
    parts.append(tokens[start:])
    return parts

def expression_source(source, tokens):
    return source[tokens[0].start:tokens[-1].end] if tokens else ''

def calls(source, tokens, owner, name):
    out = []
    pattern = [owner, '.', name, '(']
    for i in range(len(tokens) - 3):
        if [t.value for t in tokens[i:i + 4]] != pattern or any(t.kind == 'string' for t in tokens[i:i + 4]):
            continue
        end = close_at(tokens, i + 3)
        out.append({'line': tokens[i].line, 'column': tokens[i].start - source.rfind('\n', 0, tokens[i].start),
                    'start': tokens[i].start, 'end': tokens[end].end,
                    'args': comma_parts(tokens[i + 4:end]), 'tokensIndex': i})
    return out

def integer_expression(tokens, environment):
    """Never execute Lua/Python expressions; allow integer literals, names, + and -."""
    tree = ast.parse(compact(tokens), mode='eval')
    def evaluate(node):
        if isinstance(node, ast.Constant) and type(node.value) is int:
            return node.value
        if isinstance(node, ast.Name) and node.id in environment:
            return environment[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
            return evaluate(node.operand) * (-1 if isinstance(node.op, ast.USub) else 1)
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub)):
            return evaluate(node.left) + evaluate(node.right) * (-1 if isinstance(node.op, ast.Sub) else 1)
        raise ValueError('Unsupported or runtime-dependent expression: ' + compact(tokens))
    return evaluate(tree.body)

def assignments(source, tokens):
    result = []
    for i in range(len(tokens) - 2):
        if tokens[i].kind != 'identifier':
            continue
        end_lhs = i + 1
        while end_lhs + 1 < len(tokens) and tokens[end_lhs].value == '.' and tokens[end_lhs + 1].kind == 'identifier':
            end_lhs += 2
        if tokens[end_lhs].value != '=':
            continue
        start_rhs = end_lhs + 1
        end_rhs = start_rhs
        depth = 0
        while end_rhs < len(tokens):
            token = tokens[end_rhs]
            if depth == 0 and token.line != tokens[start_rhs].line:
                break
            if token.kind != 'string':
                depth += token.value in ['(', '[', '{']
                depth -= token.value in [')', ']', '}']
            end_rhs += 1
        result.append({'name': compact(tokens[i:end_lhs]), 'tokens': tokens[start_rhs:end_rhs], 'line': tokens[i].line,
                       'expression': expression_source(source, tokens[start_rhs:end_rhs])})
    return result

def snippet(source, first, last):
    return [{'line': i + 1, 'source': v} for i, v in enumerate(source.splitlines()) if first <= i + 1 <= last]

scripts_path = ROOT / 'public/native/scripts.json'
data_path = ROOT / 'public/native/card-data.json'
scripts_document = json.loads(scripts_path.read_text())
data_document = json.loads(data_path.read_text())
scripts = scripts_document['scripts']
rows = {row[0]: dict(zip(data_document['columns'], row)) for row in data_document['rows']}
lexed = {name: lex(source) for name, source in scripts.items()}
TYPE_TOKEN = 0x4000
TYPE_MONSTER = 0x1

def card_details(code):
    row = rows.get(code)
    if row is None:
        return {'code': code, 'presentInNativeCardData': False}
    return {'code': code, 'name': row['name'], 'alias': row['alias'], 'ot': row['ot'], 'type': row['type'],
            'isTokenBit': bool(row['type'] & TYPE_TOKEN),
            'isTokenMonster': bool(row['type'] & TYPE_TOKEN and row['type'] & TYPE_MONSTER),
            'sourceDatabase': row['sourceDatabase'], 'presentInNativeCardData': True}

global_environment = {}
global_bindings = []
for binding in assignments(scripts['card_counter_constants.lua'], lexed['card_counter_constants.lua']):
    try:
        value = integer_expression(binding['tokens'], global_environment)
    except (ValueError, SyntaxError):
        continue
    global_environment[binding['name']] = value
    if 'TOKEN' in binding['name']:
        global_bindings.append({'name': binding['name'], 'value': value, 'script': 'card_counter_constants.lua',
                                'line': binding['line'], 'expression': binding['expression']})

generators = []
api_calls = []
expression_histogram = Counter()
native_code_sources = defaultdict(list)
debug_calls = []
all_word_create_token = []
for filename, source in scripts.items():
    tokens = lexed[filename]
    token_calls = calls(source, tokens, 'Duel', 'CreateToken')
    for token in tokens:
        if token.kind == 'identifier' and token.value == 'CreateToken':
            all_word_create_token.append({'script': filename, 'line': token.line})
    for call in calls(source, tokens, 'Debug', 'AddCard'):
        debug_calls.append({'script': filename, 'line': call['line'], 'arguments': [expression_source(source, p) for p in call['args']],
                            'classification': 'runtime card-code parameters in Maximum helper; no TYPE_TOKEN argument or token constructor',
                            'source': source[call['start']:call['end']]})
    if not token_calls:
        continue
    match = re.fullmatch(r'c(\d+)\.lua', filename)
    if not match:
        raise ValueError('Non-card CreateToken script requires explicit review: ' + filename)
    code = int(match[1])
    if not re.search(r'local\s+s\s*,\s*id\s*=\s*GetID\s*\(\s*\)', source):
        raise ValueError('GetID origin not confirmed: ' + filename)
    environment = {**global_environment, 'id': code}
    local_bindings = []
    listed_names = []
    for binding in assignments(source, tokens):
        if binding['name'] == 's.listed_names' and binding['tokens'][0].value == '{':
            end = close_at(binding['tokens'], 0)
            for part in comma_parts(binding['tokens'][1:end]):
                try:
                    listed_names.append(integer_expression(part, environment))
                except (ValueError, SyntaxError):
                    listed_names.append({'expression': expression_source(source, part), 'unresolved': True})
        elif re.fullmatch(r'TOKEN_[A-Z_]+|[A-Z_]+_TOKEN', binding['name']):
            try:
                value = integer_expression(binding['tokens'], environment)
            except (ValueError, SyntaxError):
                continue
            environment[binding['name']] = value
            local_bindings.append({'name': binding['name'], 'value': value, 'line': binding['line'], 'expression': binding['expression']})
    generator_calls = []
    for call in token_calls:
        if len(call['args']) != 2:
            raise ValueError('Unexpected CreateToken arity')
        expr_tokens = call['args'][1]
        expr = compact(expr_tokens)
        expression_histogram[expr] += 1
        evidence = []
        conservative_codes = []
        try:
            resolved_codes = [integer_expression(expr_tokens, environment)]
            category = ('numeric-literal' if expr_tokens[0].kind == 'number' and len(expr_tokens) == 1
                        else 'constant-binding' if len(expr_tokens) == 1 else 'GetID-integer-expression')
            resolution = 'static-single-code'
        except (ValueError, SyntaxError):
            category = 'runtime-code-expression'
            resolution = 'bounded-code-domain-from-source'
            if expr == 'tk' and filename == 'c30327674.lua':
                resolved_codes = [code + 1, code + 2]
                evidence = snippet(source, 13, 16) + snippet(source, 26, 30) + snippet(source, 35, 35) + snippet(source, 74, 80)
                details = 'tk is the first effect label; initial_effect sets id+1/id+2 on the two effects registering s.tkop. listed_names corroborates those codes; it is not used alone as proof.'
            elif expr == 'id+1+i' and filename == 'c67284107.lua':
                resolved_codes = [code + 1 + i for i in range(4)]
                evidence = snippet(source, 22, 33)
                details = 'i begins at 0 and is updated to (i+1)%4; the repeat body can select codes id+1 through id+4. Number of bodies remains duel-dependent.'
            elif any(t.value == 'i' for t in expr_tokens):
                prefix = source[:call['start']]
                loops = list(re.finditer(r'for\s+i\s*=\s*(\d+)\s*,\s*([A-Za-z_0-9]+)\s+do', prefix))
                if not loops:
                    raise ValueError('Unresolved loop domain: ' + filename)
                loop = loops[-1]
                start = int(loop[1])
                if loop[2].isdigit():
                    stop = int(loop[2])
                    details = 'Enclosing numeric for-loop fixes the code domain; each code is a possible source-level iteration, not proof that the effect resolves in a duel.'
                elif filename == 'c11050415.lua' and loop[2] == 'ft':
                    stop = 4
                    resolution = 'conditional-standard-MZONE-bound'
                    conservative_codes = [integer_expression(expr_tokens, {**environment, 'i': i}) for i in range(start, 6)]
                    details = 'ft is Duel.GetLocationCount(tp,LOCATION_MZONE) after a successful SpecialSummon of Performapal Hip Hippo from hand/deck/GY. Under the standard five Main Monster Zone model this consumes one zone, leaving at most four. Lua alone does not define GetLocationCount semantics; the five-zone conservative expansion is retained separately and is not a proven reachable missing code.'
                    evidence += snippet(source, 25, 37)
                else:
                    raise ValueError('Unresolved runtime loop: ' + filename)
                resolved_codes = [integer_expression(expr_tokens, {**environment, 'i': i}) for i in range(start, stop + 1)]
                evidence += snippet(source, source.count('\n', 0, loop.start()) + 1, call['line'])
            else:
                raise ValueError('Unresolved code expression needs explicit review: ' + filename + ': ' + expr)
        record = {'script': filename, 'generatorCode': code, 'generatorName': rows.get(code, {}).get('name'),
                  'line': call['line'], 'column': call['column'], 'source': source[call['start']:call['end']],
                  'playerExpression': expression_source(source, call['args'][0]),
                  'codeExpression': expression_source(source, expr_tokens), 'normalizedCodeExpression': expr,
                  'syntaxCategory': category, 'resolution': resolution, 'codeDomain': sorted(set(resolved_codes)),
                  'nativeRows': [card_details(v) for v in sorted(set(resolved_codes))]}
        if evidence:
            record['resolutionEvidence'] = evidence
            record['resolutionDetails'] = details
        if conservative_codes:
            record['conservativeFiveZoneDomain'] = conservative_codes
            record['conservativeAbsentCandidates'] = [v for v in conservative_codes if v not in rows]
        for value in record['codeDomain']:
            native_code_sources[value].append({'generatorCode': code, 'generatorName': record['generatorName'], 'script': filename,
                                               'line': call['line'], 'expression': record['codeExpression'], 'resolution': resolution})
        api_calls.append(record)
        generator_calls.append(record)
    generators.append({'script': filename, 'code': code, 'nativeCard': card_details(code),
                       'scriptSHA256': hashlib.sha256(source.encode()).hexdigest(), 'scriptBytes': len(source.encode()),
                       'scriptSourcePath': scripts_document['files'][filename]['path'], 'callCount': len(generator_calls),
                       'callLines': [v['line'] for v in generator_calls], 'tokenCodeDomain': sorted({v for c in generator_calls for v in c['codeDomain']}),
                       'listedNames': listed_names, 'localCodeBindings': local_bindings})

token_bit_rows = [r for r in rows.values() if r['type'] & TYPE_TOKEN]
token_monster_rows = [r for r in token_bit_rows if r['type'] & TYPE_MONSTER]
direct_generator_codes = {g['code'] for g in generators}
generator_aliases = [{**card_details(r['id']), 'generatorAlias': r['alias']} for r in rows.values()
                     if r['alias'] in direct_generator_codes and r['id'] not in direct_generator_codes]
token_rows_without_direct_creation = []
for row in token_monster_rows:
    if row['id'] in native_code_sources:
        continue
    token_rows_without_direct_creation.append({**card_details(row['id']), 'description': row['desc'],
                                               'aliasHasDirectCreation': row['alias'] in native_code_sources,
                                               'aliasGenerators': native_code_sources.get(row['alias'], [])})

source_sha_mismatches = [n for n, s in scripts.items() if hashlib.sha256(s.encode()).hexdigest() != scripts_document['files'][n]['sha256']]
if source_sha_mismatches:
    raise ValueError('Source snapshot metadata SHA mismatch')
try:
    extractor_source = Path(__file__).read_text()
except (NameError, FileNotFoundError):
    extractor_source = json.loads(OUTPUT.read_text())['reproduction']['pythonExtractorSource']

inventory = {
    'format': 'native-lua-token-generator-inventory-v1',
    'auditDate': '2026-10-11',
    'generatedAtUTC': datetime.now(timezone.utc).isoformat(),
    'scope': 'Pinned public/native/scripts.json and public/native/card-data.json; lexical direct creation inventory with limited integer evaluation and explicitly bounded dynamic cases. No Lua interpreter, native duel execution, CDB/WASM mutation, or rule certification.',
    'sources': {
        'scripts': {'path': 'public/native/scripts.json', 'sha256': hashlib.sha256(scripts_path.read_bytes()).hexdigest(),
                    'bytes': scripts_path.stat().st_size, 'format': scripts_document['format'], 'provenance': scripts_document['source'],
                    'embeddedScriptSHAMismatches': source_sha_mismatches},
        'cardData': {'path': 'public/native/card-data.json', 'sha256': hashlib.sha256(data_path.read_bytes()).hexdigest(),
                     'bytes': data_path.stat().st_size, 'format': data_document['format'], 'provenance': data_document['source']},
        'helperScripts': [{'script': n, 'sha256': hashlib.sha256(scripts[n].encode()).hexdigest(), 'upstreamPath': scripts_document['files'][n]['path']}
                          for n in ['constant.lua', 'card_counter_constants.lua', 'utility.lua', 'proc_xyz.lua', 'proc_maximum.lua']]},
    'summary': {
        'scriptsScanned': len(scripts), 'nativeCardRows': len(rows),
        'directDuelCreateTokenCalls': len(api_calls), 'directGeneratorScripts': len(generators),
        'lexicalCreateTokenIdentifiers': len(all_word_create_token),
        'staticSingleCodeCallSites': sum(v['resolution'] == 'static-single-code' for v in api_calls),
        'runtimeCodeExpressionCallSites': sum(v['syntaxCategory'] == 'runtime-code-expression' for v in api_calls),
        'boundedDynamicCallSites': sum(v['resolution'] == 'bounded-code-domain-from-source' for v in api_calls),
        'conditionalStandardMZONEBoundCallSites': sum(v['resolution'] == 'conditional-standard-MZONE-bound' for v in api_calls),
        'uniqueStaticSingleCodes': len({c for v in api_calls if v['resolution'] == 'static-single-code' for c in v['codeDomain']}),
        'uniqueNativeTokenMonsterCodesInSourceDomains': len(native_code_sources),
        'missingNativeRowsInSourceDomains': sorted(c for c in native_code_sources if c not in rows),
        'nonTokenMonsterRowsInSourceDomains': sorted(c for c in native_code_sources if c in rows and not (rows[c]['type'] & TYPE_TOKEN and rows[c]['type'] & TYPE_MONSTER)),
        'tokenBitRows': len(token_bit_rows), 'trueTokenMonsterRows': len(token_monster_rows),
        'tokenBitOnlySentinelRows': len(token_bit_rows) - len(token_monster_rows),
        'tokenMonsterRowsWithoutDirectCreation': len(token_rows_without_direct_creation),
        'tokenMonsterRowsWithoutDirectCreationButWithCreatedAlias': sum(v['aliasHasDirectCreation'] for v in token_rows_without_direct_creation),
        'generatorCardAliases': len(generator_aliases), 'DebugAddCardCalls': len(debug_calls),
        'provenTrueTokenDebugAddCardCalls': 0,
        'conservativeAbsentCandidatesNotProvenReachable': sorted({c for v in api_calls for c in v.get('conservativeAbsentCandidates', [])}),
        'normalizedCodeExpressionHistogram': dict(sorted(expression_histogram.items()))},
    'method': {
        'lexing': 'Lua short and long comments omitted. Escaped short strings and Lua long bracket strings retained as opaque tokens. Balanced call/table delimiters parse top-level arguments, including nested calls. API name permits arbitrary whitespace between tokens.',
        'evaluation': 'Only integer literals, identifiers with established bindings, unary +/-, binary +/- are evaluated through a restricted AST. No eval/exec is used on Lua expressions. GetID comes from cNNN.lua and is checked in each direct generator script. s.listed_names is recorded/corroborating metadata, not a substitute for a CreateToken call.',
        'dynamicCases': 'Numeric for i domains, Chaos Witch registered-effect label flow, and Scapeghost modulo-4 loop are recorded with source lines. Super Hippo ft requires standard Main Monster Zone semantics; its conditional domain and conservative missing candidate are separate.',
        'limits': ['This inventories direct API calls and explicit source domains; it does not prove every effect or every iteration is legally reachable.',
                   'GetLocationCount native semantics are not implemented by this Lua lexer. No source-only proof claims that code 11050420 can actually be created.',
                   'Debug.AddCard in proc_maximum.lua takes caller-supplied card codes. Those calls are generic Maximum setup, with no token-type argument; their arbitrary runtime arguments are not enumerated as token generators.',
                   'A CDB alias is recorded as an alias relationship. Aliases are not counted as separate direct Lua call sites.',
                   'Token rows with no direct call and no created alias remain explicitly unmapped; descriptions are evidence, not invented native code redirection.',
                   'The three TYPE_TOKEN-only rows have no TYPE_MONSTER bit and are not included among playable token monster profiles.',
                   'No claims are made about dynamically constructed API names or arbitrary external scripts not contained in the pinned snapshot. All lexical CreateToken identifiers in this snapshot coincide with the parsed direct API calls.']},
    'globalTokenCodeBindings': global_bindings,
    'generators': sorted(generators, key=lambda v: v['code']),
    'apiCalls': sorted(api_calls, key=lambda v: (v['generatorCode'], v['line'])),
    'tokenCodeSources': [{'nativeCard': card_details(code), 'creationSites': native_code_sources[code]} for code in sorted(native_code_sources)],
    'nativeTokenMonsterRows': [{**card_details(r['id']), 'description': r['desc']} for r in token_monster_rows],
    'tokenBitOnlySentinels': [{**card_details(r['id']), 'description': r['desc']} for r in token_bit_rows if not r['type'] & TYPE_MONSTER],
    'tokenMonsterRowsWithoutDirectCreation': token_rows_without_direct_creation,
    'generatorCardAliases': generator_aliases,
    'DebugAddCardCalls': debug_calls,
    'utilityGenericPlaceholder': {
        'script': 'utility.lua', 'code': 946, 'presentInCardData': 946 in rows,
        'classification': 'c946 is a generic Card metatable placeholder with a no-op initial_effect; this block does not call CreateToken or Debug.AddCard',
        'sourceEvidence': snippet(scripts['utility.lua'], 114, 121),
        'sameNumericValueInXyzHelper': {'script': 'proc_xyz.lua', 'classification': 'SetCode(946) on Effect.CreateEffect(c), an effect identifier, not card creation',
                                      'sourceEvidence': snippet(scripts['proc_xyz.lua'], 47, 54)}},
    'reproduction': {'pythonExtractorSHA256': hashlib.sha256(extractor_source.encode()).hexdigest(),
                     'pythonExtractorSource': extractor_source,
                     'commandFromRepositoryRoot': 'python -c \'import json; exec(json.load(open("docs/audits/artifacts/token-monster-inventory-2026-10-11/lua-token-generators.json"))["reproduction"]["pythonExtractorSource"])\'',
                     'outputPath': str(OUTPUT.relative_to(ROOT))}
}

OUTPUT.parent.mkdir(parents=True, exist_ok=True)
OUTPUT.write_text(json.dumps(inventory, ensure_ascii=False, indent=2) + '\n')
print(json.dumps({'output': str(OUTPUT), 'sha256': hashlib.sha256(OUTPUT.read_bytes()).hexdigest(), 'summary': inventory['summary']}, ensure_ascii=False, indent=2))
